const views={dre:{title:'Resultado do mês',copy:'Veja o que sobrou de verdade depois de considerar receita, taxas, custos e despesas.',number:'R$ 261,81',positive:'80,7% de margem　+36,3% vs agosto'},caixa:{title:'Caixa sem surpresa',copy:'Saiba o dinheiro que entrou, o que saiu e o que ainda está previsto para os próximos dias.',number:'R$ 203,00',positive:'Entrou no mês　+R$ 337 a receber'},estoque:{title:'Estoque e CMV',copy:'Acompanhe o custo do que vendeu e entenda como o estoque impacta a sua margem.',number:'R$ 50,00',positive:'Custo do que vendeu　calculado com estoque'},vendas:{title:'Vendas que contam',copy:'Registre cada venda e veja o total, o ticket médio e as formas de pagamento.',number:'R$ 331,36',positive:'5 vendas registradas　no mês'}};
document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>{t.classList.remove('active');t.setAttribute('aria-selected','false')});tab.classList.add('active');tab.setAttribute('aria-selected','true');const v=views[tab.dataset.view];document.querySelector('#view-title').textContent=v.title;document.querySelector('#view-copy').textContent=v.copy;document.querySelector('#view-number').textContent=v.number;document.querySelector('#view-positive').textContent=v.positive}));
document.addEventListener('pointermove',e=>{const g=document.querySelector('.cursor-glow');if(g){g.style.left=`${e.clientX}px`;g.style.top=`${e.clientY}px`}});
